import re,os,sys
root='.'
files={'SKILL.md':'SKILL.md'}
for f in os.listdir('references'):
    files[f]='references/'+f
heads={}
for f,p in files.items():
    hs=set()
    for line in open(p):
        m=re.match(r'^#+\s+(.*?)\s*$',line)
        if m: hs.add(m.group(1))
        m=re.match(r'^\*\*(.+?)\*\*\s*$',line)
        if m: hs.add(m.group(1))
    heads[f]=hs
allheads=set().union(*heads.values())
pat=re.compile(r'`(?:references/)?([A-Za-z-]+\.md)`(?:\'s)?(?:,| section| part,|\'s section)?\s*((?:"[^"]+"(?:,? (?:and|or) |, )?)+)')
for f,p in files.items():
    if f=='sources.md': continue
    txt=open(p).read()
    for m in pat.finditer(txt):
        tgt=m.group(1)
        for q in re.findall(r'"([^"]+)"',m.group(2)):
            if tgt not in heads:
                print('NOFILE',f,tgt,q); continue
            if q not in heads[tgt]:
                print('MISSING',f,'->',tgt,repr(q))
    # quotes not preceded by a file ref: check same-file or any heading
    for m in re.finditer(r'"([^"]{3,80})"',txt):
        q=m.group(1)
        pre=txt[max(0,m.start()-40):m.start()]
        if '.md`' in pre: continue
        if q in heads[f]: continue
        if q in allheads: print('OTHERFILE',f,repr(q),'in',[g for g in heads if q in heads[g]])
        else: print('QUOTE',f,repr(q))
# files referenced
for f,p in files.items():
    txt=open(p).read()
    for m in re.findall(r'`(?:references/)?([A-Za-z-]+\.md)`',txt):
        if m not in files and m not in ('README.md','REPORT.md','CLAUDE.md'): print('REF-NONEXIST',f,m)
EOF
